import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and case classes for algebraic data types
 * - Type classes for polymorphic behavior
 * - Option/Either for error handling
 * - Immutable data structures
 * - Higher-order functions and functional patterns
 */

// ============================================================================
// Enums and Core Types
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }

  val values: Seq[TokenType] = Seq(String, Numeric, Temporal, Structured, Binary, Null)

  def fromString(s: String): Option[TokenType] = values.find(_.value == s)
}

// ============================================================================
// Core Token Classes
// ============================================================================

final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

final class MutableTokenBatch private (
    private val tokens: mutable.ListBuffer[Token],
    private var processed: Boolean
) {
  def add(token: Token): Either[RuntimeException, Unit] =
    if (processed) Left(new RuntimeException("Batch already processed"))
    else {
      tokens += token
      Right(())
    }

  def markProcessed(): Unit = processed = true

  def getTokens: List[Token] = tokens.toList

  def isProcessed: Boolean = processed
}

object MutableTokenBatch {
  def apply(): MutableTokenBatch = new MutableTokenBatch(mutable.ListBuffer.empty, false)
}

// ============================================================================
// Type Classes for Tokenization
// ============================================================================

trait Tokenizable[A] {
  def toToken(a: A): String
}

object Tokenizable {
  def apply[A](implicit ev: Tokenizable[A]): Tokenizable[A] = ev

  implicit val stringTokenizable: Tokenizable[String] = (a: String) => a
  implicit val intTokenizable: Tokenizable[Int] = (a: Int) => a.toString
  implicit val longTokenizable: Tokenizable[Long] = (a: Long) => a.toString
  implicit val doubleTokenizable: Tokenizable[Double] = (a: Double) => a.toString
  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] = (a: BigDecimal) => a.toString
}

trait HasLength[A] {
  def length(a: A): Int
}

object HasLength {
  def apply[A](implicit ev: HasLength[A]): HasLength[A] = ev

  implicit val stringHasLength: HasLength[String] = (a: String) => a.length
  implicit def seqHasLength[T]: HasLength[Seq[T]] = (a: Seq[T]) => a.length
  implicit def arrayHasLength[T]: HasLength[Array[T]] = (a: Array[T]) => a.length
}

trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens(func: A => String): Vector[String] = _items.map(func)
}

object TokenContainer {
  def apply[A](items: Seq[A]): TokenContainer[A] = new TokenContainer(items)
  def empty[A]: TokenContainer[A] = new TokenContainer(Seq.empty)
}

class TokenSink[-A] {
  private val received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: A): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

object TokenSink {
  def apply[A](): TokenSink[A] = new TokenSink[A]
}

class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = _value = value

  def transform(func: A => A): A = {
    _value = func(_value)
    _value
  }
}

object BivariantHandler {
  def apply[A](default: A): BivariantHandler[A] = new BivariantHandler(default)
}

// ============================================================================
// Tokenizer Trait and Implementations
// ============================================================================

trait BaseTokenizer[A] {
  def tokenize(value: A): Token

  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.String)
  }

  def tokenizeBytes(value: Array[Byte]): Token = {
    val strValue = new String(value, encoding)
    tokenize(strValue)
  }
}

object StringTokenizer {
  def apply(
      encoding: String = "UTF-8",
      normalizer: String => String = identity
  ): StringTokenizer = new StringTokenizer(encoding, normalizer)
}

sealed trait NumericValue
object NumericValue {
  final case class IntValue(v: Int) extends NumericValue
  final case class LongValue(v: Long) extends NumericValue
  final case class DoubleValue(v: Double) extends NumericValue
  final case class BigDecimalValue(v: BigDecimal) extends NumericValue
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  def tokenize(value: NumericValue): Token = {
    import NumericValue._
    val (strValue, originalType) = value match {
      case IntValue(v) => (v.toString, "Int")
      case LongValue(v) => (v.toString, "Long")
      case DoubleValue(v) => (s"%.${precision}f".format(v), "Double")
      case BigDecimalValue(v) =>
        (v.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString, "BigDecimal")
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }

  def tokenizeInt(value: Int): Token = tokenize(NumericValue.IntValue(value))
  def tokenizeLong(value: Long): Token = tokenize(NumericValue.LongValue(value))
  def tokenizeDouble(value: Double): Token = tokenize(NumericValue.DoubleValue(value))
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(NumericValue.BigDecimalValue(value))
}

object NumericTokenizer {
  def apply(
      precision: Int = 6,
      formatOptions: Map[String, Any] = Map.empty
  ): NumericTokenizer = new NumericTokenizer(precision, formatOptions)
}

sealed trait TemporalValue
object TemporalValue {
  final case class DateTime(v: LocalDateTime) extends TemporalValue
  final case class Date(v: LocalDate) extends TemporalValue
}

class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalValue] {
  import TemporalTokenizer._

  def tokenize(value: TemporalValue): Token = {
    val formatted = (value, formatStr) match {
      case (TemporalValue.DateTime(dt), Some(fmt)) =>
        dt.format(DateTimeFormatter.ofPattern(fmt))
      case (TemporalValue.DateTime(dt), None) =>
        dt.format(IsoFormatter)
      case (TemporalValue.Date(d), Some(fmt)) =>
        d.format(DateTimeFormatter.ofPattern(fmt))
      case (TemporalValue.Date(d), None) =>
        d.format(DateFormatter)
    }
    Token(formatted, TokenType.Temporal)
  }

  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(TemporalValue.DateTime(value))
  def tokenizeDate(value: LocalDate): Token = tokenize(TemporalValue.Date(value))
}

object TemporalTokenizer {
  val IsoFormatter: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  val DateFormatter: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def apply(formatStr: Option[String] = None): TemporalTokenizer = new TemporalTokenizer(formatStr)
}

// ============================================================================
// Universal Tokenizer with Pattern Matching
// ============================================================================

sealed trait TokenizableValue
object TokenizableValue {
  final case class StringVal(v: String) extends TokenizableValue
  final case class BytesVal(v: Array[Byte]) extends TokenizableValue
  final case class IntVal(v: Int) extends TokenizableValue
  final case class LongVal(v: Long) extends TokenizableValue
  final case class DoubleVal(v: Double) extends TokenizableValue
  final case class BigDecimalVal(v: BigDecimal) extends TokenizableValue
  final case class DateTimeVal(v: LocalDateTime) extends TokenizableValue
  final case class DateVal(v: LocalDate) extends TokenizableValue
  final case class CustomTokenizable(toToken: () => String) extends TokenizableValue
  case object NullVal extends TokenizableValue
}

class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  def tokenize(value: TokenizableValue): Token = {
    import TokenizableValue._
    value match {
      case NullVal => Token("NULL", TokenType.Null)
      case CustomTokenizable(toToken) => Token(toToken(), TokenType.Structured)
      case StringVal(v) => stringTokenizer.tokenize(v)
      case BytesVal(v) => stringTokenizer.tokenizeBytes(v)
      case IntVal(v) => numericTokenizer.tokenizeInt(v)
      case LongVal(v) => numericTokenizer.tokenizeLong(v)
      case DoubleVal(v) => numericTokenizer.tokenizeDouble(v)
      case BigDecimalVal(v) => numericTokenizer.tokenizeBigDecimal(v)
      case DateTimeVal(v) => temporalTokenizer.tokenizeDateTime(v)
      case DateVal(v) => temporalTokenizer.tokenizeDate(v)
    }
  }
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer
}

// ============================================================================
// Token Registry with Generics
// ============================================================================

class TokenRegistry[A] {
  private val registry: mutable.Map[String, TokenContainer[A]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[A => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[A]): Unit =
    registry(key) = container

  def addHandler(handler: A => Option[Token]): Unit =
    handlers += handler

