  def apply(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Tokenizer Builder with Fluent Interface
// ============================================================================

class TokenizerBuilder[A] private (
    private val normalizers: Vector[String => String],
    private val validators: Vector[A => Boolean],
    private val metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries.toMap)

  def build(): A => Either[String, Token] = { value =>
    validators.find(v => !v(value)) match {
      case Some(_) => Left(s"Validation failed for $value")
      case None =>
        val strValue = normalizers.foldLeft(value.toString) { (s, norm) => norm(s) }
        Right(Token(strValue, TokenType.String, metadata))
    }
  }

  def buildUnsafe(): A => Token = { value =>
    build()(value) match {
      case Right(token) => token
      case Left(error) => throw new IllegalArgumentException(error)
    }
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] =
    new TokenizerBuilder(Vector.empty, Vector.empty, Map.empty)
}
